import os
from bedrock_agentcore.runtime import BedrockAgentCoreApp
from strands import Agent
from strands.models.openai import OpenAIModel

class GatewayModel(OpenAIModel):
    """OpenAIModel, without an empty tool list (see below)."""
    def format_request(self, *args, **kwargs):
        request = super().format_request(*args, **kwargs)
        if not request.get("tools"):
            request.pop("tools", None)
        return request

MODEL = GatewayModel(
    client_args={"base_url": os.environ["OPENAI_BASE_URL"],   # agentgateway, set by the operator
                 "api_key": os.environ["OPENAI_API_KEY"]},
    model_id=os.environ.get("MODEL_ALIAS", "nemotron-nano-9b"),  # a ModelConfig alias
    params={"max_tokens": 500, "temperature": 0},
)
app = BedrockAgentCoreApp()

@app.entrypoint
def invoke(payload):
    question = (payload.get("context") or {}).get("question", "")
    return {"answer": str(Agent(model=MODEL, callback_handler=None)(question))}

if __name__ == "__main__":
    app.run()
```
